ANNOTATIONS = [
    (30, 'before', '''inputSchema：action 二选一（keep 保留 / remove 删除），discard_changes 是 remove 时的二次确认开关。'''),
    (62, 'before', '''ChangeSummary：未提交文件数 + 基线后的提交数，remove 前的安全度量。'''),
    (78, 'after', '''countWorktreeChanges 的 doc 注释把失败语义说死了：**返回 null = 状态不可判定，调用方必须按「未知即不安全」处理（fail-closed）**。静默返回 0/0 会让 cleanupWorktree 销毁真实工作——注释里列了两种 null 成因：git 命令非零退出（锁文件/索引损坏/坏 ref），以及 originalHeadCommit 缺失（hook 创建的 worktree 包着 git 的情况，看得见工作区却数不了提交）。'''),
    (83, 'before', '''git status --porcelain 数改动文件：退出码非零直接 null，不猜。'''),
    (94, 'before', '''status 成功但没有基线提交：能确认是 git 仓库，却证明不了分支干净——宁可拒删也不谎报 0。'''),
    (100, 'before', '''git rev-list --count baseline..HEAD 数新提交，两个 git 调用都是 execFileNoThrow（不抛异常，退出码走返回值）。'''),
    (121, 'after', '''restoreSessionToOriginalCwd：EnterWorktreeTool.call() 会话级改动的**逆运算**。注释划清了边界——keepWorktree/cleanupWorktree 管进程 chdir 和当前 worktree 会话，这个函数管它们之上的一切（全局 cwd、originalCwd、projectRoot、hooks 快照、各种缓存）。'''),
    (126, 'after', '''setCwd(originalCwd) 把工作目录换回去；下一行 setOriginalCwd(originalCwd) 同样指向真实原目录——EnterWorktree 那边故意存的是 worktree 路径，这里必须改回来，否则退出后「原始目录」概念一直错位。'''),
    (135, 'before', '''projectRoot 只在该过的时候才复原：--worktree 启动会把 projectRoot 设成 worktree，会话中途 EnterWorktree 不动它。不判断就直接 setProjectRoot(originalCwd)，会把 projectRoot 挪到用户进 worktree 前随便 cd 到的某个目录，破坏「稳定项目身份」契约。hooks 配置快照同理对称恢复——启动时从 worktree 重读过，退出时就该重读回来。'''),
    (148, 'before', '''ExitWorktreeTool：退出并决定 worktree 去留。'''),
    (168, 'before', '''isDestructive：action 为 remove 时为真——权限分类器据此提高审批档位，keep 则是无害操作。'''),
    (174, 'before', '''validateInput：三道关卡全在这里，call() 只执行。'''),
    (180, 'before', '''scope 闸：getCurrentWorktreeSession() 仅当 EnterWorktree（确切说 createWorktreeForSession）在**本会话**跑过才非空。用户手敲 git worktree add 建的、上个会话建的，都不 populated——这是唯一入口闸，过了它后面操作的所有路径都是 EnterWorktree 创建的。'''),
    (190, 'before', '''remove 且未显式 discard_changes：先数账再决定放不放行。'''),
    (195, 'before', '''数不出账（null）→ errorCode 3 拒绝删除，提示改用 discard_changes: true 强拆或改 keep。'''),
    (203, 'before', '''有未提交文件或新提交 → errorCode 2 拒绝删除，消息里列明数量和分支名，要求先与用户确认再带 discard_changes: true 重调。删除不可逆，对话框必须让人看见代价。'''),
    (227, 'before', '''call() 执行段。'''),
    (250, 'before', '''projectRootIsWorktree 判定：getProjectRoot() === getOriginalCwd() 说明启动时 --worktree 把两者设成了同一值（mid-session EnterWorktree 只设 originalCwd）。不能用 getCwd()——BashTool 每次 cd 都改它；也不能用 session.worktreePath——那是 join 出来的没做过 realpath。'''),
    (256, 'before', '''执行时重新数账：validateInput 到 call() 之间隔着用户审批，worktree 状态可能变了。这里的数字只用于遥测和结果消息（安全闸门在 validateInput 已经过了），null 退化成 0/0 无安全隐患。'''),
    (261, 'before', '''keep 分支：保留目录和分支，只做状态复原；tmux 会话不杀，把会话名回在消息里教用户 reattach。'''),
    (287, 'before', '''remove 分支：先杀 tmux 会话（还挂着一个活 tmux 删目录会留下孤儿窗格），再 cleanupWorktree 删目录和分支。'''),
    (322, 'before', '''tool_result 同样只带 message 字符串。'''),
]
